function event_death_complete(e)
  -- PEQ reuses this NPC on 6B and 7. Only the upper-floor bats can spawn Tserrina.
  -- P99 specifies either Tserrina or a vampire, at the bat's corpse, never both.
  if e.self:GetZ() >= 300 and math.random(100) <= 16
    and not eq.get_entity_list():IsMobSpawnedByNpcTypeID(111154) then
    eq.unique_spawn(111154, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
  else
    eq.spawn2(111174, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading())
  end
end
